        [Theory]
        [MemberData(nameof(Expected90))]
        public void ClassicThemeSameAs90(string scenario, string expected)
        {
            PagerSettings.DefaultTheme = PagerTheme.Classic;
            try
            {
                Assert.Equal(expected, Normalize(Render(scenario)));
            }
            finally
            {
                PagerSettings.ResetDefaultTheme();
            }
        }

        private static string Normalize(string s) =>
            Regex.Replace(WebUtility.HtmlDecode(s), " (aria-[a-z]+|role|rel)=\"[^\"]*\"", "").Replace("'", "\"");

        private static string Url(int p) => "/items?page=" + p;

        private static string Data(IPager<int> p) =>
            $"items=[{string.Join(",", p)}] cur={p.CurrentPageIndex} size={p.PageSize} total={p.TotalItemCount} pages={p.TotalPageCount} " +
            $"prev={p.HasPreviousPage} next={p.HasNextPage} first={p.IsFirstPage} last={p.IsLastPage} start={p.StartItemIndex} end={p.EndItemIndex}";

        private static string Try(Func<string> f)
        {
            try { return f(); } catch (Exception ex) { return "THROWS " + ex.GetType().Name; }
        }

        private static string Render(string scenario)
        {
            var items = Enumerable.Range(1, 200).ToList();
            var p1 = items.ToPagerList(1, 20);
            var p3 = items.ToPagerList(3, 20);
            var p10 = items.ToPagerList(10, 20);
            string H(IPager pg, PagerOptions? o = null) => (o == null ? P.Pager.Mvc.Core.HtmlHelper.Pager(null!, pg, Url) : P.Pager.Mvc.Core.HtmlHelper.Pager(null!, pg, Url, o)).ToString()!;
            IPager Pick(string s) => s.EndsWith(" p1") ? p1 : s.EndsWith(" p3") ? p3 : p10;
            string preset = scenario.Contains(' ') ? scenario[..scenario.LastIndexOf(' ')] : scenario;
            return Try(() => scenario switch
            {
                "page 1" => Data(items.ToPagerList(1, 20)),
                "page 3" => Data(items.ToPagerList(3, 20)),
                "last page" => Data(items.ToPagerList(10, 20)),
                "past end 12" => Data(items.ToPagerList(12, 20)),
                "page 0" => Data(items.ToPagerList(0, 20)),
                "page -5" => Data(items.ToPagerList(-5, 20)),
                "partial last" => Data(Enumerable.Range(1, 45).ToPagerList(3, 20)),
                "defaults" => Data(items.ToPagerList()),
                "queryable" => Data(items.AsQueryable().ToPagerList(2, 20)),
                "AsPagerList" => Data(items.AsQueryable().AsPagerList(2, 20)),
                "async enumerable" => Data(items.ToPagerListAsync(2, 20).Result),
                "async queryable" => Data(items.AsQueryable().ToPagerListAsync(2, 20).Result),
                "async null page" => Data(items.AsQueryable().ToPagerListAsync(null, 20).Result),
                "pageSize -1" => Data(items.ToPagerList(1, -1)),
                "PagesToDisplay 10" => H(p3, new PagerOptions { PagesToDisplay = 10 }),
                "TextToIndividualPages" => H(p3, new PagerOptions { TextToIndividualPages = "Page-{0}" }),
                "custom words" => H(p3, new PagerOptions { TextToPreviousPage = "Previous Page", TextToNextPage = "Next Page", TextToFirstPage = "First Page", TextToLastPage = "Last Page" }),
                "custom classes + delimiter" => H(p3, new PagerOptions { ClassToUl = "list-inline", ClassToLi = "list-inline-item", PageClass = "nopageclass", ClassToActiveLi = "niloclass", TextForDelimiter = " | " }),
                "icons" => H(p3, new PagerOptions { TextToPreviousPage = "<i class='bi bi-skip-start'></i>", TextToNextPage = "<i class='bi bi-skip-end'></i>" }),
                "container class" => H(p3, new PagerOptions { ClassToPagerContainer = "my-pager" }),
                "url with query" => P.Pager.Mvc.Core.HtmlHelper.Pager(null!, p3, p => "/items?q=a b&page=" + p).ToString()!,
                _ => preset switch
                {
                    "default" => H(Pick(scenario)),
                    "Minimal" => H(Pick(scenario), PrePagerOptions.Minimal),
                    "MinimalWithPagerText" => H(Pick(scenario), PrePagerOptions.MinimalWithPagerText),
                    "MinimalWithEntriesText" => H(Pick(scenario), PrePagerOptions.MinimalWithEntriesText),
                    "ClassicPager" => H(Pick(scenario), PrePagerOptions.ClassicPager),
                    "ClassicFirstLast" => H(Pick(scenario), PrePagerOptions.ClassicPagerWithFirstAndLastPages),
                    _ => throw new InvalidOperationException("Unknown scenario " + scenario),
                },
            });
        }
    }
}
